package cn.zhuatech.fpa.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class ForecastSubmissionGovernanceServiceTest{private final ForecastSubmissionGovernanceService service=new ForecastSubmissionGovernanceService();@Test void submitsGovernedForecast(){var r=service.assess(new ForecastSubmissionGovernanceService.Request("2026-M09",true,true,true,true,true,false,true,true));assertThat(r.decision()).isEqualTo(ForecastSubmissionGovernanceService.Decision.SUBMIT);}@Test void blocksFinancialControlGaps(){var r=service.assess(new ForecastSubmissionGovernanceService.Request("2026-M10",false,false,false,false,false,true,true,true));assertThat(r.blockers()).hasSize(6);}@Test void reviewsVarianceAndScenarioGaps(){var r=service.assess(new ForecastSubmissionGovernanceService.Request("2026-M11",true,true,true,true,true,false,false,false));assertThat(r.actions()).hasSize(2);}}
